insert into public.books (
  id, slug, title, long_title, author_id, author_name, author_note, year, category,
  status, isbn, price_idr, image_url, back_image_url, color, description, featured
) values
  (1, 'mencari-muhammad-historis', 'Mencari Muhammad Historis', 'Mencari Muhammad Historis: Menyingkap Tabir Misteri Suci', 'author-maruf-rusafi', 'Ma’ruf Rusafi', 'Sastrawan Irak', '2026', 'Studi Islam', 'Telah terbit', '978-623-0000-26-1', null, '/assets/mencari-muhammad-front.png', '/assets/mencari-muhammad-back.png', 'blue', 'Siapakah Nabi Muhammad yang sesungguhnya? Nabi dalam iman yang ceritanya dilebih-lebihkan dalam bentuk mukjizat dan hal supranatural lainnya, atau sosok historis yang masih menyimpan banyak misteri? Bagaimana jika kisah-kisah dan sejarah kemunculan Islam awal mengenai Nabi Muhammad selama ini dibangun dari sumber yang perlu dibaca ulang dan dipertanyakan kesahihannya? Benarkah Islam tersebar karena mukjizat al-Qur’an, atau ada kekuatan lain yang selama ini ditutupi oleh narasi mapan? Melalui karyanya yang berjudul Kitab al-Syakhshiyyah al-Muhammadiyyah aw Hall al-Lughz al-Muqaddas, Ma''ruf al-Rusafi melakukan observasi kritis dengan membongkar sirah, hadis, tafsir, dan bahkan sisi balaghah al-Qur’an yang selama ini dipercayai sebagai dogma. Terjemahan buku karya Ma''ruf al-Rusafi ini tidak menawarkan jawaban yang nyaman, ia mengajak pembaca memasuki wilayah paling kontroversial dalam pencarian Nabi Muhammad sebagai sosok agung dalam Islam.', true),
  (2, 'anak-anak-kampung-kami', 'Anak-Anak Kampung Kami', 'Anak-Anak Kampung Kami', 'author-nagib-mahfuz', 'Nagib Mahfuz', 'Novelis Mesir', 'Segera hadir', 'Sastra Dunia', 'Akan terbit', '978-623-0000-26-2', null, '/assets/anak-anak-kampung-front.png', '/assets/anak-anak-kampung-back.png', 'warm', 'Di sebuah kampung, nama Gabalawi hidup dalam cerita dan ingatan. Rumah besarnya menyimpan kemegahan, sementara anak-cucunya bergulat dengan kemiskinan, ketakutan, dan kekuasaan para preman. Mereka mewarisi janji tentang kehidupan yang adil. Namun, siapakah yang akan menepatinya? Dari Adham hingga Gabal, Rifaa, dan Qasim, harapan terus tumbuh. Ada yang melawan dengan kekuatan. Ada yang menawarkan kasih dan pengampunan. Ada yang menyatukan mereka yang tercerai-berai. Lalu datang Arafa, membawa pengetahuan yang menjanjikan jalan baru yang sekaligus membuka pintu bagi bahaya yang tak terduga. Melalui kisah sebuah kampung, Nagib Mahfuz membentangkan pergulatan manusia dengan iman, kekuasaan, dan kerinduan akan keadilan. Tokoh-tokohnya mengingatkan kita pada kisah-kisah suci yang akrab, tetapi membawa kita ke dunia yang penuh kejutan. Di sini, para pembebas dapat dikenang sementara cita-cita mereka dilupakan. Janji keselamatan pun dapat berubah menjadi alat kekuasaan. Anak-Anak Kampung Kami mengajak kita memasuki dunia yang hangat, keras, dan meresahkan. Sebuah novel yang terus menggugah pertanyaan, bahkan setelah halaman terakhir ditutup: Jika para pembebas telah datang dan pergi, siapakah yang akan mengubah nasib kampung ini?', true),
  (3, 'polemik-kitab-suci', 'Polemik Kitab Suci', 'Polemik Kitab Suci', 'author-munim-sirry', 'Mun’im Sirry', 'Dosen Universitas Notre Dame', 'Segera hadir', 'Kajian Al-Qur’an', 'Akan terbit', '978-623-0000-26-3', null, '/assets/polemik-kitab-suci-front.png', '/assets/polemik-kitab-suci-back.png', 'lavender', 'Buku ini merupakan kajian akademis atas ayat-ayat polemik Al-Qur’an dan penafsirannya oleh ulama-ulama modern. Enam tafsir modern karya pembaru Muslim dari berbagai belahan dunia diuji secara kritis untuk menyingkap pandangan serta tantangan yang mereka hadapi dalam menafsirkan Kitab Suci dalam konteks dunia yang berbeda. Salah satu argumen utama buku ini ialah bahwa tafsir Al-Qur’an modern merupakan wacana penafsiran yang jauh lebih kaya dan lentur daripada yang selama ini diasumsikan. Tafsir-tafsir pembaru ditelaah dengan perhatian saksama terhadap argumen dan konteks sosio-historis untuk memperjelas metode, posisi, serta cakrawala penafsirannya. Proses ini berlangsung dalam dua arah: pembacaan kritis atas tafsir-tafsir tersebut, serta penelusuran yang jernih dan orisinal terhadap bahasa, retorika, dan dilema Al-Qur’an dalam lima topik perdebatan yang telah menyita perhatian para sarjana lintas agama. Hasilnya ialah sebuah karya dengan jangkauan konseptual yang luas dan kepekaan terhadap kompleksitas wacana keagamaan. Buku ini membuka wilayah kajian baru tentang polemik Kitab Suci, sekaligus sumbangan berharga bagi sejumlah bidang, termasuk studi Al-Qur’an, sejarah tafsir, serta perbincangan teologis yang melibatkan agama-agama Ibrahimik dan, secara lebih luas, agama-agama dunia.', true),
  (4, 'interaksi-islam', 'Interaksi Islam', 'Interaksi Islam', 'author-munim-sirry', 'Mun’im Sirry', 'Esai-esai pilihan', '2024', 'Studi Islam', 'Telah terbit', '978-623-0000-24-4', 100000, '/assets/interaksi-islam-front.png', '/assets/interaksi-islam-back.png', 'green', 'Sebelas esai yang terkumpul dalam buku ini, kendati mendiskusikan beragam tema, mempunyai benang merah yang sama, yakni hendak menggambarkan bahwa Islam merupakan agama yang membentuk dan dibentuk oleh pergulatan (engagement) yang tak pernah selesai. Yang dimaksud dengan “pergulatan” di sini ialah penafsiran yang terus berlangsung atas teks-teks fondasional dan interaksi resiprokal dengan konteks-konteks sosiohistoris yang melingkupi kemunculan dan perkembangan Islam dari zaman ke zaman. Sementara yang pertama (penafsiran atas teks) memang merupakan ciri utama dari pergulatan dengan Kitab Suci, yakni interpretasi dan reinterpretasi, yang kedua (interaksi dengan konteks sosiohistoris) juga tak terelakkan karena Islam, atau agama apapun dalam hal ini, lahir dan berkembang bukan dalam ruang hampa. Islam yang kita saksikan saat ini merupakan hasil dari pergulatan dan pergumulan yang melibatkan beragam penafsiran yang dipromosikan, dinegosiasikan, diperdebatkan, dan akhirnya terbentuk sebagai sistem keimanan yang terus berkembang dan berubah dalam kurun waktu berbeda dan lokasi berbeda.', false),
  (5, 'pendidikan-dan-radikalisme', 'Pendidikan dan Radikalisme', 'Pendidikan dan Radikalisme', 'author-munim-sirry', 'Mun’im Sirry', 'Riset lapangan', '2023', 'Pendidikan Publik', 'Telah terbit', '978-623-0000-23-5', 125000, '/assets/pendidikan-radikalisme-front.png', '/assets/pendidikan-radikalisme-back.png', 'coral', 'Buku ini didasarkan pada hasil penelitian lapangan yang dilakukan pada tahun 2018 dan 2019 dengan tujuan memahami, mendokumentasikan, dan menganalisis pandangan siswa SMA tentang keragaman agama, etnik, budaya dan orientasi politik, serta apa yang menyebabkan mahasiswa terpapar paham radikal. Dengan gabungan metode kuantitatif dan kualitatif, buku ini menyuguhkan data dan teori cukup gamblang, yang diharapkan membantu kita memahami fenomena intoleransi di kalangan anak muda terpelajar. Yang unik dari buku ini ialah pemaparannya yang meletakkan potret intoleransi dan radikalisme di Indonesia dalam bingkai yang lebih luas pada tataran dunia global.', false),
  (6, 'kemunculan-islam', 'Kemunculan Islam dalam Kesarjanaan Revisionis', 'Kemunculan Islam dalam Kesarjanaan Revisionis', 'author-munim-sirry', 'Mun’im Sirry', 'Studi sejarah', '2017 / 2019', 'Sejarah', 'Telah terbit', '978-623-0000-17-6', 90000, '/assets/kemunculan-islam-front.png', '/assets/kemunculan-islam-back.png', 'blue', 'Buku ini ditulis tidak untuk meragukan, apalagi mengubah keyakinan anda, para pembaca. Sebuah keyakinan itu terbentuk melalui proses yang panjang sehingga tak mungkin tergoyahkan oleh tawaran gagasan yang dikembangkan dalam buku ini. Tujuan saya sebenarnya cukup sederhana. Yakni, mengajukan sebuah perspektif tentang proses kemunculan Islam ke atas panggung sejarah. Potret historis kelahiran Islam atau Islamic origins yang disuguhkan buku ini berbeda dari keyakinan umum kaum Muslim. Karena itu, jika anda termasuk pembaca yang akan tersinggung manakala pemahaman konvensional anda dipertanyakan, maka saya anjurkan untuk tidak membaca buku ini. Saya juga tidak menganjurkan buku ini bagi mereka yang akan menelan mentah-mentah setiap informasi dan analisis at face value. Sejujurnya, saya tidak khawatir bahwa buku ini akan kehilangan pembaca, karena kedua model pembaca di atas tidaklah signifikan dari segi jumlah, jikapun ada. Tujuan buku ini ialah untuk menstimulasi munculnya pertanyaan-pertanyaan yang menggugah (bahkan, mungkin bagi sebagian orang dianggap provokatif), walaupun mungkin kita tidak bersepakat tentang jawabannya.', false),
  (7, 'koeksistensi-islam-kristen', 'Koeksistensi Islam-Kristen', 'Koeksistensi Islam-Kristen', 'author-munim-sirry', 'Mun’im Sirry', 'Refleksi lintas iman', '2023', 'Dialog Antaragama', 'Telah terbit', '978-623-0000-23-7', 80000, '/assets/koeksistensi-islam-kristen-front.png', null, 'purple', 'Relasi Islam dan Kristen dalam rentang sejarah yang panjang kerap digambarkan penuh ketegangan, konflik, bahkan perang berdarah. Penaklukan dan perang salib menjadi bagian dari lembaran hitam hubungan kedua komunitas agama terbesar ini. Juga, sentimen negatif yang mengemuka akibat kekhawatiran “Islamisasi” atau Kristenisasi.” Buku ini menyuguhkan gambaran koeksistensi Islam-Kristen yang berbeda. Bukan berarti ketegangan dan konflik itu tak pernah ada, melainkan bukan cerita segalanya. Ada sisi-sisi lain dari hubungan Kristen dan Muslim yang kerap diabaikan. Memang, perjumpaan kedua agama diwarnai dengan rivalitas, permusuhan dan kompetisi. Namun demikian, ada juga momen dialog terbuka, kolaborasi saling menguntungkan, dan persahabatan sejati yang tidak lusuh karena konflik. Saya berharap refleksi-refleksi santai dalam buku ini dapat menginspirasi pembaca untuk meningkatkan kesadaran akan kebersamaan. Kita perlu berikhtiar untuk berkembang bersama dalam keragaman. Kepedulian dan solidaritas kemanusiaan perlu terus ditumbuhkan. Masyarakat plural seperti Indonesia harus mensinergikan keragaman untuk perdamaian dan kemajuan bersama. Tak akan ada perdamaian di dunia tanpa koeksistensi antar-umat beragama. Tak akan ada koeksistensi antar-umat beragama tanpa persahabatan dan kerjasama antara Muslim dan Kristen. Tak akan ada kerjasama antara Muslim dan Kristen tanpa saling pengertian dan respek antar sesama umat manusia. Semoga buku ini membantu ke arah itu.', false),
  (8, 'rekonstruksi-islam-historis', 'Rekonstruksi Islam Historis', 'Rekonstruksi Islam Historis', 'author-munim-sirry', 'Mun’im Sirry', 'Untuk pembaca luas', '2021', 'Sejarah', 'Telah terbit', '978-623-0000-21-8', 110000, '/assets/rekonstruksi-islam-historis-front.png', '/assets/rekonstruksi-islam-historis-back.png', 'ink', 'Buku ini ditulis untuk audiens pembaca yang luas: Akademisi, mahasiswa, aktivis dialog antar-agama, pemerhati studi agama-agama, dan pembaca umum. Rekonstruksi Islam Historis mendiskusikan pertanyaan-pertanyaan krusial yang sejak lama cenderung diabaikan dalam studi Islam. Bukti apa yang kita miliki untuk merekonstruksi kemunculan Islam? Kenapa sumber-sumber Muslim yang tersedia saat ini problematik untuk menyingkap peristiwa-peristiwa penting yang terjadi pada abad pertama Islam, seperti kehidupan Nabi, kodifikasi al-Qur’an atau penaklukan dan ekspansi wilayah? Bagaimana problem permulaan Islam sebagai fenomena historis itu dibingkai? Buku ini menguraikan pertanyaan di atas dan pertanyaan-pertanyaan serupa dengan merujuk pada sumber-sumber primer dan sekunder, sembari memperlihatkan perdebatan metodologis di kalangan sarjana-sarjana modern. Dengan spirit menyambut perspektif yang beragam untuk mendorong iklim perdebatan yang sehat, buku ini mengeksplorasi berbagai gagasan, metode, dan paradigma yang berseberangan. Spektrum kesarjanaan revisionis dan tradisionalis yang luas juga dihadirkan untuk mendeteksi perkembangan-perkembangan mutakhir dalam kesarjanaan modern tentang Islam, secara khusus, dan tentang kemunculan agama-agama, secara umum. Diharapkan, buku ini menghidupkan (kembali) gairah intelektual untuk mendiskusikan gagasan-gagasan penting yang menghiasi cakrawala kesarjanaan mutakhir.', false),
  (9, 'think-outside-the-box', 'Think Outside the Box', 'Think Outside the Box', 'author-munim-sirry', 'Mun’im Sirry', 'Catatan dengan perspektif baru', '2024', 'Esai', 'Telah terbit', '978-623-0000-24-9', 98000, '/assets/think-outside-box-front.png', '/assets/think-outside-box-back.png', 'orange', 'Buku ini seperti rekaman catatan harian yang membicarakan masalah-masalah lama dengan perspektif baru. Ia lahir dari perbincangan di dunia media sosial (medsos). Walaupun tidak seluruh tulisan dalam buku ini telah dipublikasikan di medsos, namun ide-ide dasarnya sudah pernah di-shared di Facebook. Dalam beberapa kesempatan, saya menulis status berseri tentang tema tertentu. Misalnya, soal menafsirkan al-Qur’an dengan Alkitab atau soal nikah beda agama. Tema-tema tersebut ditulis untuk memberikan wawasan kepada pembaca umum. Tidak perlu detail, namun langsung menukik ke jantung permasalahan. Diharapkan, tulisan-tulisan pendek dapat menginspirasi pembacaan lebih lanjut. Dalam buku ini gaya tutur yang populer tersebut masih tetap dipertahankan.', false)
on conflict (id) do nothing;

select setval(pg_get_serial_sequence('public.books', 'id'), greatest(coalesce((select max(id) from public.books), 1), 1), true);

